events=[]
armed=False
class M(type):
 def __hash__(cls):
  events.append(('hash', cls.__name__))
  return cls.h
 def __eq__(cls, other):
  events.append(('eq', cls.__name__, other.__name__))
  if armed:
   raise ValueError('comparison')
  return cls is other
class A(metaclass=M): h=0
class B(metaclass=M): h=1
class C(metaclass=M): h=0
class D(metaclass=M): h=2
class F(frozenset):
 def __eq__(self, other): raise AssertionError("override")
 def __ne__(self, other): raise AssertionError("override")
 __hash__=frozenset.__hash__
left=F([A,B])
right=F([C,D])
T=frozenset
events.clear()
armed=True
try:
 value=left == right
 result=("ok", value)
except BaseException as error:
 result=(type(error).__name__, error.args)
result=(result,events)

